local function rt() local e=math.floor(tick()-st) tV.Text=string.format("%02d:%02d",math.floor((e%3600)/60),e%60) end
local function ps() VIM:SendKeyEvent(true,Enum.KeyCode.Space,false,game) task.wait(0.1) VIM:SendKeyEvent(false,Enum.KeyCode.Space,false,game) end
local function oI() if not on then return end local n=tick() if n-li<1 then return end li=n iN+=1 iV.Text=tostring(iN) ps() lg("Sonic · Idled 触发") end
local function oH() if not on then return end if tick()-la>=240 then la=tick() hN+=1 hV.Text=tostring(hN) pcall(ps) lg("Sonic · 保活心跳",Color3.fromRGB(100,160,255)) end end
U.InputBegan:Connect(function() if on then la=tick() uN+=1 uV.Text=tostring(uN) end end) R.Heartbeat:Connect(function() if on then rt() end end)
local function start() on=true st=tick() la=tick() iN,hN,uN=0,0,0 iV.Text,hV.Text,uV.Text="0","0","0" ic=pl.Idled:Connect(oI) hc=R.Heartbeat:Connect(oH) tg.Text="Sonic · 关闭防挂机" tg.BackgroundColor3=Color3.fromRGB(0,200,140) ts.Color=Color3.fromRGB(0,200,140) sD.BackgroundColor3=Color3.fromRGB(0,200,140) sL.Text="Sonic · 运行中" sL.TextColor3=Color3.fromRGB(0,200,140) lg("Sonic · 已开启",Color3.fromRGB(0,200,140)) end
local function stop() on=false if ic then ic:Disconnect() ic=nil end if hc then hc:Disconnect() hc=nil end tg.Text="Sonic · 开启防挂机" tg.BackgroundColor3=Color3.fromRGB(38,38,46) ts.Color=Color3.fromRGB(70,70,85) sD.BackgroundColor3=Color3.fromRGB(100,100,110) sL.Text="Sonic · 未开启" sL.TextColor3=Color3.fromRGB(160,160,175) lg("Sonic · 已关闭",Color3.fromRGB(255,100,100)) end
tg.MouseButton1Click:Connect(function() if on then stop() else start() end end)
local dg,ds,sp=false,nil,nil hd.InputBegan:Connect(function(i) if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then dg=true ds=i.Position sp=m.Position i.Changed:Connect(function() if i.UserInputState==Enum.UserInputState.End then dg=false end end) end end)
U.InputChanged:Connect(function(i) if dg and (i.UserInputType==Enum.UserInputType.MouseMovement or i.UserInputType==Enum.UserInputType.Touch) then local d=i.Position-ds m.Position=UDim2.new(sp.X.Scale,sp.X.Offset+d.X,sp.Y.Scale,sp.Y.Offset+d.Y) end end)
